### Expression Canvas — Recursive Tree Renderer

The tree renderer is the heart of the Creative paradigm. It converts `math.parse()` output into interactive HTML:

```javascript
function renderNode(node, cursorPath, depth, scope, mode) {
    const isCursorHere = pathsEqual(cursorPath, currentNodePath(node, cursorPath));
    const type = getCachedType(node, scope);  // Uses scope cache
    const typeSymbol = { number: 'ℝ', Complex: 'ℂ', DenseMatrix: 'M', boolean: '𝔹', string: 'S' }[type];

    // Render this node as a card
    return `
        <div class="expr-node ${isCursorHere ? 'cursor' : ''}" 
             style="margin-left: ${depth * 20}px">
            <span class="type-badge type-${type}">${typeSymbol}</span>
            <span class="node-value">${nodeValuePreview(node, scope)}</span>
            ${hasChildren(node) ? `<div class="node-children">${renderChildren(node, cursorPath, depth, scope, mode)}</div>` : ''}
            ${hasPreviewPanel(node) ? renderPreviewPanel(node, scope, mode) : ''}
        </div>`;
}
```

**Type badge evaluation** uses the scope cache:
```javascript
const evalCache = new Map();
function getCachedType(node, scope) {
    const key = node.toString();
    if (evalCache.has(key)) return evalCache.get(key).type;
    try {
        const value = node.evaluate(scope);
        const type = math.typeOf(value);
        evalCache.set(key, { value, type });
        return type;
    } catch(e) {
        return 'error';
    }
}
```

**Scope cache invalidation:** Cleared on every `Input.handleAction()` call (any keystroke changes the expression).

### Numerical Methods — Scope Injection Pattern

```javascript
const numericalScope = {
    integrate: function(exprStr, a, b, n = 100) {
        const compiled = math.compile(exprStr);
        const f = (x) => compiled.evaluate({ x });
        const h = (b - a) / n;
        let sum = f(a) + f(b);
        for (let i = 1; i < n; i++) 
            sum += (i % 2 === 0 ? 2 : 4) * f(a + i * h);
        return (h / 3) * sum;
    },
    derivative: function(exprStr, xVal, h = 1e-8) {
        const compiled = math.compile(exprStr);
        const f = (x) => compiled.evaluate({ x });
        return (f(xVal + h) - f(xVal - h)) / (2 * h);
    },
    solve: function(exprStr, x0, tol = 1e-10) {
        const compiled = math.compile(exprStr);
        const f = (x) => compiled.evaluate({ x });
        let x = x0;
        for (let i = 0; i < 200; i++) {
            const fx = f(x);
            if (Math.abs(fx) < tol) return x;
            const df = (f(x + 1e-8) - f(x - 1e-8)) / (2e-8);
            if (Math.abs(df) < 1e-15) break;
            x = x - fx / df;
        }
        return x;
    }
};

// Usage: passed as scope to every evaluate call
math.evaluate(expr, { ...numericalScope, ...userVariables });
```

### REAL/COMPLEX Mode Detection — Deferred Type Judgment

```javascript
function detectComplexResult(result, mode) {
    if (mode.numberDomain === 'COMPLEX') return { error: false };
    if (math.typeOf(result) !== 'Complex') return { error: false };
    if (Math.abs(result.im) < 1e-15) return { error: false };  // Effectively real
    return { error: true, message: 'Complex result in REAL mode. Switch to COMPLEX mode or wrap in re/abs/im.' };
}
```

For the Expression Canvas, deferred judgment walks ancestor nodes:

```javascript
const COMPLEX_ABSORBERS = ['im', 'abs', 'arg', 'norm', 'real', 'sign'];
function deferredTypeCheck(node, ancestors, mode) {
    // Check if any ancestor absorbs Complex → Real
    const hasAbsorber = ancestors.some(a => COMPLEX_ABSORBERS.includes(a.fn?.name));
    if (hasAbsorber) return { error: false, note: 'wrapped' };

    // No absorber — Complex leaks to top level
    return detectComplexResult(math.evaluate(node.toString()), mode);
}
```

### Error Handling — AST-Based Silent Error Detection

```javascript
function detectSilentErrors(node) {
    const errors = [];

    // Pattern 1: Zero-arg function call (sin(), cos(), etc.)
    if (node.type === 'FunctionNode' && node.args.length === 0 && node.fn?.name !== 'random') {
        errors.push({ type: 'zero-arg', message: `${node.fn.name}() called with no arguments` });
    }

    // Pattern 2: det(scalar)
    if (node.type === 'FunctionNode' && node.fn?.name === 'det' && node.args.length === 1) {
        try {
            const argVal = node.args[0].evaluate();
            if (math.typeOf(argVal) === 'number') {
                errors.push({ type: 'det-scalar', message: `det(${argVal}) = ${argVal}. Use det([value]) for 1×1 matrix.` });
            }
        } catch(e) {}
    }

    // Pattern 3: 0^0
    if (node.type === 'OperatorNode' && node.op === '^' &&
        node.left.type === 'ConstantNode' && node.left.value === 0 &&
        node.right.type === 'ConstantNode' && node.right.value === 0) {
        errors.push({ type: 'zero-power-zero', message: '0^0 is mathematically indeterminate. Returns 1 by convention.' });
    }

    // Recurse
    if (node.args) node.args.forEach(a => errors.push(...detectSilentErrors(a)));
    if (node.left) errors.push(...detectSilentErrors(node.left));
    if (node.right) errors.push(...detectSilentErrors(node.right));

    return errors;
}
```

